package com.qpwflshclub.formal_club.social;
import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import static org.assertj.core.api.Assertions.*;
class AccountProfilesTest {
 @TempDir Path root;
 @Test void studentNumberIsUniqueImmutableAndPersists()throws Exception{var store=new AccountProfiles(root.resolve("profiles.json").toString());store.register("a@example.com","00123","Nick",true,()->true);assertThatThrownBy(()->store.register("b@example.com","00123","Other",true,()->true)).hasMessageContaining("409");assertThatThrownBy(()->store.update("a@example.com",new AccountProfiles.Profile("00456","","","",List.of(),""),true)).hasMessageContaining("409");assertThat(new AccountProfiles(root.resolve("profiles.json").toString()).get("a@example.com").studentNumber()).isEqualTo("00123");}
 @Test void failedRegistrationReleasesNumberAndConcurrentClaimsHaveOneWinner()throws Exception{var store=new AccountProfiles(root.resolve("profiles.json").toString());assertThatThrownBy(()->store.register("a@example.com","100","",true,()->{throw new RuntimeException("DB failed");})).hasMessageContaining("DB failed");assertThat(store.get("a@example.com").studentNumber()).isEmpty();try(var pool=Executors.newFixedThreadPool(6)){var calls=new ArrayList<Callable<Boolean>>();for(int i=0;i<10;i++){int n=i;calls.add(()->{try{return store.register("user"+n+"@example.com","100","",true,()->true);}catch(org.springframework.web.server.ResponseStatusException e){return false;}});}assertThat(pool.invokeAll(calls).stream().filter(f->{try{return f.get();}catch(Exception e){throw new RuntimeException(e);}}).count()).isEqualTo(1);}}
 @Test void tagsAreBoundedAndTeacherCannotSetStudentFields()throws Exception{var store=new AccountProfiles(root.resolve("profiles.json").toString());var p=store.update("t@shwfl.edu.cn",new AccountProfiles.Profile("123","张老师","G10","1",List.of("Robotics","Robotics"),"Hello"),false);assertThat(p.studentNumber()).isEmpty();assertThat(p.grade()).isEmpty();assertThat(p.tags()).containsExactly("Robotics");}
}
